r.append(R(7616374,"तोरई कॉर्नब्रेड मफ़िन और सालसा",
"तोरई और प्याज़ से भरे और ऊपर से तीखे पुदीने वाले टमाटर सालसा के साथ ये मिनी कॉर्न मफ़िन पूरे परिवार को पसंद आएँगे।",
"30","50 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 लाल प्याज़, बारीक कटा हुआ","1 लाल शिमला मिर्च, बारीक कटी हुई","1 तोरई, कद्दूकस की हुई","1 छोटा चम्मच ओरेगानो","2 अंडे, फेंटे हुए","200 मिली स्किम्ड दूध","2 बड़े चम्मच 0% फ़ैट वाला ग्रीक योगर्ट","150 ग्राम पोलेंटा (मक्के का दरदरा आटा)","150 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग पाउडर","30 ग्राम पुराना चेडर, कद्दूकस किया हुआ",
["सालसा के लिए","4 टमाटर (200 ग्राम), बारीक कटे हुए"],["सालसा के लिए","1 हरी मिर्च, बारीक कटी हुई"],["सालसा के लिए","3 टहनियाँ पुदीना, कटा हुआ"],["सालसा के लिए","1 छोटा चम्मच सिरका"]],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें और मिनी मफ़िन टिन में तेल लगाएँ (या स्प्रे करें)।","एक पैन में 1 छोटा चम्मच तेल डालें, उसमें प्याज़ और लाल शिमला मिर्च डालकर 6-7 मिनट तक नरम होने तक पकाएँ।","आँच से उतारें और तोरई और ओरेगानो डालकर मिलाएँ, फिर अलग रख दें।","एक कटोरे में अंडा, दूध और योगर्ट को मिलाएँ। फिर पोलेंटा, आटा और बेकिंग पाउडर डालकर दोबारा मिलाएँ, फिर सब्ज़ियाँ और कद्दूकस किया हुआ चीज़ मिला दें।","इसे मिनी मफ़िन टिन में या मिनी पेपर केस में चम्मच से भरें। 15-20 मिनट तक हल्का भूरा होने तक बेक करें।","इस बीच, सालसा बनाने के लिए टमाटर, मिर्च, पुदीना और सिरका मिलाएँ।"],
["आप अलग सब्ज़ियाँ इस्तेमाल कर सकते हैं, पके हुए मक्के या मटर के साथ आज़माएँ, या तोरई की जगह पका हुआ पालक डालें।","यदि आपके पास मिनी मफ़िन टिन नहीं हैं, तो आप मिनी पेपर केस इस्तेमाल कर सकते हैं।"]))
r.append(R(7616762,"सेब और किशमिश के रॉक केक",
"ये बनाने में झटपट और आसान हैं और साबुत अनाज के फ़ाइबर से भरपूर हैं, एक पौष्टिक और स्वादिष्ट व्यंजन के लिए। बच्चों के साथ इन्हें बनाने में भी बहुत मज़ा आता है।",
"12","68 ग्राम",
["चिकनाई लगाने के लिए 1 छोटा चम्मच रेपसीड तेल","300 ग्राम साबुत गेहूँ का आटा","1 ढेर वाला छोटा चम्मच बेकिंग पाउडर","1 छोटा चम्मच दालचीनी","1 केला","1 मध्यम अंडा","50 ग्राम बारीक चीनी","75 मिली रेपसीड तेल","1 छोटा चम्मच वनीला एसेंस","1 सेब, बीज निकाला हुआ, बिना छिला और बारीक कटा हुआ","75 ग्राम किशमिश (सुल्ताना)"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें और एक बड़ी बेकिंग शीट पर रेपसीड तेल की हल्की चिकनाई लगाएँ।","एक कटोरे में आटा, बेकिंग पाउडर और दालचीनी मिलाएँ।","दूसरे कटोरे में केले को काँटे से मसलें, अंडा डालें और अच्छी तरह फेंटें। इसमें चीनी, तेल, वनीला एसेंस और 50 मिली पानी मिलाएँ।","सूखी सामग्री को धीरे-धीरे केले और अंडे के मिश्रण में मिलाएँ, फिर किशमिश और सेब मिला दें।","चिकनाई लगी बेकिंग शीट पर मिश्रण के 12 छोटे, बेतरतीब ढेर लगाएँ और काँटे से कई छोटे-छोटे काँटे जैसे उभार बना दें।","18-22 मिनट तक बेक करें, फिर ओवन से निकालकर वायर रैक पर ठंडा होने दें।"],
["इन्हें गरम-गरम खाना सबसे अच्छा है, लेकिन इन्हें एयरटाइट डिब्बे में 2-3 दिन तक रखा जा सकता है।","आप दालचीनी की जगह पिसा मिक्स्ड स्पाइस, अदरक, जायफल या इलायची जैसे अन्य मसाले डाल सकते हैं।","केला डालने का मतलब है कि आप कम चीनी और वसा का उपयोग करते हैं, जबकि पोषक तत्व बढ़ जाते हैं।","फ्रीज़र बैग में, फ़ॉइल या ग्रीसप्रूफ़ पेपर में लपेटकर, तीन महीने तक फ्रीज़ करें।"]))
r.append(R(7618221,"गार्लिक ब्रेड",
"कैरामेलाइज़्ड प्याज़, लहसुन और पार्सले से भरी और मक्खन की जगह जैतून के तेल वाली, यह गार्लिक ब्रेड क्लासिक रेसिपी का कम वसा वाला संस्करण है।",
"24","36 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","3 मध्यम प्याज़, बारीक कटे हुए","6-10 फांक लहसुन, कुचला हुआ","25 ग्राम पार्सले, कटा हुआ","एक पिसाई काली मिर्च","1 बड़ा चम्मच जैतून का तेल","1 बैगेट (लगभग 300 ग्राम)","50 ग्राम हाफ़-फ़ैट मोज़ारेला, कद्दूकस किया हुआ"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। एक सॉसपैन में तेल डालकर धीमी आँच पर रखें, प्याज़ डालें और बीच-बीच में चलाते हुए 25 मिनट तक धीरे-धीरे पकाएँ, जब तक कि वे कैरामेलाइज़ न होने लगें, भूरे और नरम न हो जाएँ। यदि वे चिपकने लगें, तो एक छोटा चम्मच पानी डालें।","इस बीच, कुचला हुआ लहसुन, कटा हुआ पार्सले, काली मिर्च और जैतून का तेल मिलाकर अलग रख दें।","बैगेट को 2 सेमी मोटे गोल टुकड़ों में काटें, लेकिन केवल लगभग तीन-चौथाई तक काटें ताकि ब्रेड जुड़ी रहे।","प्याज़ को लहसुन और पार्सले के मिश्रण में मिलाएँ। ब्रेड के हर गोल टुकड़े के बीच एक चम्मच भरें, इसे स्लाइसों में बराबर बाँटें।","ब्रेड को पूरी तरह फ़ॉइल में लपेटें और 10-12 मिनट तक बेक करें। फ़ॉइल खोलें, ऊपर से मोज़ारेला चीज़ डालें और परोसने से पहले 5 मिनट और बेक करें।"],
["प्याज़ को कैरामेलाइज़ करने से वे कच्ची मात्रा के लगभग एक-तिहाई रह जाते हैं। उन्हें बहुत धीमी आँच पर पकाना और लकड़ी के चम्मच से बीच-बीच में चलाते रहना ज़रूरी है।","फ़ाइबर की मात्रा बढ़ाने के लिए साबुत गेहूँ का बैगेट इस्तेमाल करें।","फ्रीज़ करने के निर्देश: पकाने के लिए तैयार या पकी हुई, दोनों अवस्था में फ्रीज़ की जा सकती है। स्लाइस करें, फिर फ्रीज़ करने के लिए फ़ॉइल में लपेट दें। फिर आप ज़रूरत के अनुसार स्लाइस पिघला सकते हैं।",FV(0)]))
r.append(R(7619702,"संतरे और तुलसी की चटनी के साथ ट्राउट",
"यह मछली का व्यंजन नए आलू और भरपूर सब्ज़ियों या सलाद के साथ परोसने पर उत्कृष्ट लगता है।",
"2","157 ग्राम",
["2 बिना हड्डी और बिना त्वचा के ट्राउट फ़िलेट (हर एक का वज़न लगभग 100 ग्राम)","1 संतरे का कद्दूकस किया हुआ छिलका और रस","2 बड़े चम्मच तुलसी, हाथ से फाड़ी हुई","2 बड़े चम्मच हाफ़-फ़ैट क्रीम फ्रेश","ताज़ा पिसी हुई काली मिर्च"],
["ट्राउट फ़िलेट को नॉन-स्टिक फ्राइंग पैन में रखें।","ऊपर से संतरे का छिलका और रस डालें, ढक दें और ट्राउट के पकने तक 5–6 मिनट धीमी आँच पर पकाएँ।","तुलसी और क्रीम फ्रेश को धीरे से मिलाएँ और गरम करें। स्वादानुसार मसाला डालें।"],
["कई सुपरमार्केट पारंपरिक छोटी मछली के फ़िलेट की जगह बड़ी ट्राउट के मोटे कटे स्टेक भी बेचते हैं। इन्हें पूरी तरह पकने में थोड़ा ज़्यादा समय लगता है (आकार के आधार पर 2–3 मिनट अधिक)।","आप तुलसी की जगह सोआ (डिल) या पार्सले का उपयोग कर सकते हैं।",FV(0)]))
r.append(R(7619710,"ब्रसल्स स्प्राउट ग्रैटिन",
"ब्रसल्स स्प्राउट्स को हल्के चीज़ सॉस में बेक किया जाता है और ऊपर से पार्मेज़ान डाला जाता है।",
"4","209 ग्राम",
["1 छोटा चम्मच जैतून का तेल","1 प्याज़, कटा हुआ","1 बड़ा चम्मच मैदा","एक अच्छी चुटकी सफ़ेद मिर्च","1 छोटा चम्मच साबुत दाने वाली सरसों","300 मिली स्किम्ड दूध","30 ग्राम कम वसा वाला पुराना चेडर","20 ग्राम पार्मेज़ान","300 ग्राम ब्रसल्स स्प्राउट्स","1 बड़ा चम्मच साबुत गेहूँ की ब्रेड का चूरा"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। एक पैन में जैतून का तेल गरम करें, प्याज़ डालें और 4 मिनट तक नरम होने तक पकाएँ, भूरा न होने दें।","प्याज़ पर लपेटने के लिए मैदा डालें, एक अच्छी चुटकी सफ़ेद मिर्च और साबुत दाने वाली सरसों मिलाएँ। गाढ़ा होने तक धीरे-धीरे दूध मिलाते रहें।","आधा चेडर और आधा पार्मेज़ान डालें और पिघलने तक 2–3 मिनट चलाएँ। इस बीच, स्प्राउट्स को उबलते पानी में 7–8 मिनट तक उबालें।","पानी निथारकर ओवन-सुरक्षित डिश में रखें, ऊपर से सॉस डालें और साबुत गेहूँ की ब्रेड का चूरा और बचा हुआ चेडर व पार्मेज़ान बुरक दें। 12–15 मिनट तक बेक करें, जब तक ऊपर से सुनहरा भूरा न हो जाए।"],
["अतिरिक्त स्वाद के लिए 2–3 फांक कुचला हुआ लहसुन या 1 बड़ा चम्मच ताज़ी कटी जड़ी-बूटियाँ, जैसे धनिया या चाइव्स, डालें।","इस व्यंजन में सब्ज़ियों की मात्रा बढ़ाने के लिए 150 ग्राम बटन मशरूम या कटा हुआ एक लीक डालें।","त्योहारी अनुभव के लिए 150 ग्राम वैक्यूम-पैक पके हुए चेस्टनट डालें।","फ्रीज़ करने के निर्देश: फ्रिज में या माइक्रोवेव में पिघलाएँ, फिर "+HOT,FV(1)]))
